const fs = require('node:fs');
const path = require('node:path');
const config = require('./lib/config');
const D = require('./lib/db');
const { createApp, listen } = require('./lib/app');
const { createUser, findByEmail } = require('./lib/users');
const { createProfile } = require('./lib/profiles');
const storage = require('./lib/storage');
const { encrypt } = require('./lib/util');
const auth = require('./routes/auth');
const pages = require('./views/pages');

// Built-in tones (generated by scripts/make-tones.py). The document id is the file name without extension.
const BUILT_IN_TONES = [
  ['Amazing Grace', 'The much-loved hymn, played slowly on organ', 'amazing-grace.mp3', 1],
  ['Taps', 'The bugle call of farewell, softened for strings', 'taps.mp3', 2],
  ['Long Road Home', 'A slow, hopeful organ melody', 'long-road-home.mp3', 3],
  ['Quiet Lantern', 'Strings in a minor key, tender and still', 'quiet-lantern.mp3', 4],
  ['Evening Stillness', 'Soft, wordless chords for quiet reflection', 'evening-stillness.mp3', 5],
];

/** Runs once at start-up: loads settings and creates the starter data if it's missing. */
async function bootstrap() {
  if (config.isProd && (config.sessionSecret.startsWith('dev-only') || !/^[0-9a-f]{64}$/i.test(config.encryptionKey))) {
    console.error('Set SESSION_SECRET and a 64-character hex ENCRYPTION_KEY in .env before running in production.');
    process.exit(1);
  }
  await D.loadSettings();
  const tones = await D.getMany('tones', BUILT_IN_TONES.map(([, , file]) => file.replace(/\.\w+$/, '')));
  const batch = D.db.batch(); let writes = 0;
  for (const [title, description, file, sort] of BUILT_IN_TONES) {
    const id = file.replace(/\.\w+$/, '');
    if (!tones.has(id) && fs.existsSync(path.join(config.ROOT, 'public', 'tones', file))) {
      batch.set(D.col('tones').doc(id), { title, description, file, sort, active: true }); writes++;
    }
  }
  if (writes) await batch.commit();
  if (!(await D.first(D.col('charities')))) {
    await D.col('charities').add({ name: 'Partner hospital (add yours)', kind: 'hospital', location: 'Nigeria', description: 'Edit or replace this placeholder in Admin, Charity.', active: true, given: 0, created_at: D.now() });
  }
  // First admin from environment variables
  if (config.adminPassword && !(await D.first(D.col('users').where('role', '==', 'admin')))) {
    const existing = await findByEmail(config.adminEmail);
    if (existing) await D.col('users').doc(existing.id).update({ role: 'admin' });
    else await createUser({ email: config.adminEmail, password: config.adminPassword, full_name: 'tillwemeet Admin', role: 'admin' });
    console.log(`Admin account ready: ${config.adminEmail}`);
  }
  // The local test memorial lives in data/local-firestore.json, which Vercel never receives.
  // Recreate it on the temporary store so production shows the same published page.
  if (process.env.VERCEL && D.mode === 'local' && !(await D.getDoc('slugs', 'test-record-2024'))) {
    const admin = await findByEmail(config.adminEmail);
    const photo = 'demo-test-record.jpg';
    const cert = 'demo-test-record-cert.png';
    await storage.put('public', photo, fs.readFileSync(path.join(config.ROOT, 'scripts/seed-assets/portrait-00.jpg')));
    await storage.put('private', cert, fs.readFileSync(path.join(config.ROOT, 'scripts/seed-assets/sample-certificate.png')));
    const { id } = await createProfile({
      creator_id: admin.id, creator_name: admin.full_name, category: 'regular',
      titles: 'Mr', first_name: 'Test', middle_name: '', last_name: 'Record', nickname: 'Demo', gender: 'Male',
      dob: '1948-03-12', dod: '2024-06-18', country: 'Nigeria', state: 'Lagos', lga: 'Ikeja',
      place_of_death: 'Ikeja General Hospital', cause_of_death: '', burial_date: '2024-06-22', burial_place: 'Family compound, Ikeja',
      biography: 'Test Record was a neighbour, a teacher and the person everyone called when something needed doing. This memorial was created as a sample so the site can be reviewed. The dates, places and story are fictional.',
      epitaph: '', survivors: '', photo, tone_id: null, video: null, video_duration: null, gallery: [], timeline: [], service_events: [],
      death_cert: cert, death_cert_number: 'NPC/TEST/000001', death_cert_authority: 'National Population Commission',
      uploader_relationship: 'Son', uploader_nin_enc: encrypt('12345678901'), uploader_nin_last4: '8901',
      uploader_photo: null, uploader_id_doc: null, uploader_phone: '08031234567', uploader_address: '12 Allen Avenue, Ikeja',
      next_of_kin_name: 'Ada Record', next_of_kin_phone: '08039876543', attested_at: D.now(),
    });
    const now = D.now();
    await D.col('profiles').doc(id).update({ status: 'approved', approved_at: now, approved_by: admin.id, listing_amount: 10000, listing_paid_at: now });
    D.bustCache();
    console.log('Demo memorial ready: /m/test-record-2024');
  }
}

const app = createApp();
app.errorPage = async (req, status, msg) => { if (req.user === undefined) await auth.loadUser(req, null).catch(() => {}); return pages.errorPage(req, status, msg); };

// Load the signed-in user for every request
const routeGet = app.get; const routePost = app.post;
app.get = (p, ...h) => routeGet(p, auth.loadUser, ...h);
app.post = (p, ...h) => routePost(p, auth.loadUser, ...h);

auth.register(app);
require('./routes/public').register(app);
require('./routes/memorials').register(app);
require('./routes/account').register(app);
require('./routes/payments').register(app);
require('./routes/admin').register(app);

app.get('/robots.txt', (req, res) => { res.writeHead(200, { 'Content-Type': 'text/plain' }); res.end('User-agent: *\nDisallow: /admin\nDisallow: /account\n'); });

app.ready = bootstrap();

// Vercel loads this file and requires the export to be a request function or an
// http.Server. A plain app object makes the runtime exit with FUNCTION_INVOCATION_FAILED.
async function handler(req, res) {
  try {
    await app.ready;
    await app.handle(req, res);
  } catch (e) {
    console.error(e);
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Could not start');
    }
  }
}
handler.ready = app.ready;
handler.handle = app.handle;

if (require.main === module) {
  app.ready.then(() => listen(app, config.port)).then(() => {
    console.log(`tillwemeet running at ${config.baseUrl} (port ${config.port})`);
    console.log(`Database: ${{ firebase: 'Firebase Firestore', emulator: 'Firestore emulator', local: 'local Firestore-compatible file store (development only)' }[D.mode]}`);
    console.log(config.paymentsLive ? 'Payments: Paystack (live keys)' : 'Payments: SIMULATED. Set PAYSTACK_SECRET_KEY to take real payments.');
  }).catch((e) => { console.error('Could not start:', e.message); process.exit(1); });
}

module.exports = handler;
